const input = $input.first().json;

let sqft = Number(input.landSize);

if (input.unit === "Katha") {
  sqft *= 720;
}
if (input.unit === "Bigha") {
  sqft *= 14400;
}

return [{
  json: {
    ...input,
    totalSqft: sqft
  }
}];

const html = $input.first().json.body || "";

const regex = /<h3[^>]*>(.*?)<\/h3>[\s\S]*?৳\s*([\d,]+)[\s\S]*?(Ton|ton)/gi;

const items = [];
let match;

while ((match = regex.exec(html)) !== null) {
  const brand = match[1].replace(/<[^>]+>/g, "").trim();
  const price = Number(match[2].replace(/,/g, ""));
  const unit = match[3];

  if (!brand || !price) continue;
  if (brand.toLowerCase().includes("call for price")) continue;

  items.push({
    brand,
    price,
    unit
  });
}

return [{
  json: {
    rodAds: items
  }
}];

const d = $input.first().json;

const totalArea = d.totalSqft * Number(d.floors);

// Basic assumptions
const bricks = Math.round(totalArea * 8);
const cementBags = Math.round(totalArea * 0.4);
const rodTons = Number((totalArea * 0.004).toFixed(2));

// Cost calculations
const rodCost = rodTons * d.price; // rod branch price
const cementCost = cementBags * d.price_1; // cement branch price

return [{
  json: {
    ...d,
    totalArea,
    bricks,
    cementBags,
    rodTons,
    rodCost,
    cementCost
  }
}];

const html = $input.first().json.body || "";

const regex = /<h3[^>]*>(.*?)<\/h3>[\s\S]*?৳\s*([\d,]+)[\s\S]*?(50\s*KG|Bag)/gi;

const items = [];
let match;

while ((match = regex.exec(html)) !== null) {
  const brand = match[1].replace(/<[^>]+>/g, "").trim();
  const price = Number(match[2].replace(/,/g, ""));
  const unit = match[3];

  if (!brand || !price) continue;
  if (brand.toLowerCase().includes("call for price")) continue;

  items.push({
    brand,
    price,
    unit
  });
}

return [{
  json: {
    cementAds: items
  }
}];

const rawOutput = $json.output;

try {
  // This converts the string "{\"rod\": ...}" into a real JavaScript object
  const parsedOutput = JSON.parse(rawOutput);
  return {
    estimate: parsedOutput
  };
} catch (e) {
  // If parsing fails, return the raw text so the workflow doesn't crash
  return {
    estimate: rawOutput
  };
}
